`});const pipeline=device.createRenderPipeline({layout:'auto',vertex:{module,entryPoint:'vs'},fragment:{module,entryPoint:'fs',targets:[{format}]}}),buffer=device.createBuffer({size:32,usage:GPUBufferUsage.UNIFORM|GPUBufferUsage.COPY_DST}),bind=device.createBindGroup({layout:pipeline.getBindGroupLayout(0),entries:[{binding:0,resource:{buffer}}]});device.lost.then(()=>{if(epoch===state.shaderEpoch){setText('#shader-mode','RECOVERING');initSpectral()}});gpuCanvas.style.display='block';fallbackCanvas.style.display='none';setText('#shader-mode','WEBGPU');const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;function frame(ms){if(epoch!==state.shaderEpoch)return;const data=new Float32Array([gpuSize.w,gpuSize.h,reduced?0:ms/1000,state.sessions.filter(s=>s.health_state==='WORKING').length/Math.max(1,state.sessions.length),Math.min(1,state.recoveries/4),state.continuity,Math.min(1,state.sessions.length/23),0]);device.queue.writeBuffer(buffer,0,data);const encoder=device.createCommandEncoder(),pass=encoder.beginRenderPass({colorAttachments:[{view:context.getCurrentTexture().createView(),clearValue:[.96,.97,.98,1],loadOp:'clear',storeOp:'store'}]});pass.setPipeline(pipeline);pass.setBindGroup(0,bind);pass.draw(3);pass.end();device.queue.submit([encoder.finish()]);requestAnimationFrame(frame)}requestAnimationFrame(frame)}catch(e){setText('#shader-mode','CANVAS 2D');gpuCanvas.style.display='none';fallbackCanvas.style.display='block'}}
new ResizeObserver(()=>{sizeSpectral();drawChronograph()}).observe(stage);new ResizeObserver(drawChronograph).observe(q('#chrono-wrap'));
sizeSpectral();initSpectral();refreshWriteState();refreshSessions();refreshEvents();refreshDrain();setInterval(refreshSessions,2000);setInterval(refreshEvents,2000);setInterval(refreshDrain,2000);setInterval(refreshReconcile,4000);
